package it.unipi.p2pb;

/** Le utility che le slide usano senza mostrarle (bytesToHex, hexToAscii, ...). */
public final class Util {
    private Util() {}

    private static final char[] HEX = "0123456789abcdef".toCharArray();

    /** Un byte come due cifre esadecimali, es. (byte) 0xAC -> "ac". */
    public static String byteToHex(byte b) {
        return "" + HEX[(b >> 4) & 0xf] + HEX[b & 0xf];
    }

    /** Array di byte come stringa esadecimale, nell'ordine in cui stanno in memoria. */
    public static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder(bytes.length * 2);
        for (byte b : bytes) sb.append(byteToHex(b));
        return sb.toString();
    }

    /** "48656c6c6f" -> byte {0x48, 0x65, ...}. */
    public static byte[] hexStringToByteArray(String hex) {
        int n = hex.length();
        byte[] out = new byte[n / 2];
        for (int i = 0; i < n; i += 2)
            out[i / 2] = (byte) Integer.parseInt(hex.substring(i, i + 2), 16);
        return out;
    }

    /** Ogni coppia di cifre esadecimali diventa un carattere (anche se non stampabile). */
    public static String hexToAscii(String hex) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i + 1 < hex.length(); i += 2)
            sb.append((char) Integer.parseInt(hex.substring(i, i + 2), 16));
        return sb.toString();
    }
}

