package it.unipi.p2pb;

import java.nio.charset.StandardCharsets;
import org.bitcoinj.base.Sha256Hash;
import org.bitcoinj.base.BitcoinNetwork;
import org.bitcoinj.base.LegacyAddress;
import org.bitcoinj.base.ScriptType;
import org.bitcoinj.crypto.ECKey;
import org.bitcoinj.script.Script;
import org.bitcoinj.script.ScriptBuilder;

/** Slide 6: la stessa chiave codificata in tutti i tipi di indirizzo. Chiave fissa (SHA-256 di una frase), così l'output è riproducibile. */
public class AddressTypes {
    public static void main(String[] args) {
        byte[] priv = Sha256Hash.hash("p2pb lab02".getBytes(StandardCharsets.UTF_8));
        ECKey key = ECKey.fromPrivate(priv);                      // MAI usarla davvero: chiunque può ricalcolarla
        BitcoinNetwork main = BitcoinNetwork.MAINNET;
        BitcoinNetwork test = BitcoinNetwork.TESTNET;

        System.out.println("pubkey    " + key.getPublicKeyAsHex());
        System.out.println("hash160   " + Util.bytesToHex(key.getPubKeyHash()));
        System.out.println();
        System.out.println("P2PKH       mainnet " + key.toAddress(ScriptType.P2PKH, main));
        System.out.println("P2PKH       testnet " + key.toAddress(ScriptType.P2PKH, test));

        // Nested SegWit: lo script P2WPKH (0 <hash160>) diventa il redeem script di un P2SH
        Script redeem = ScriptBuilder.createP2WPKHOutputScript(key);
        byte[] redeemHash = org.bitcoinj.crypto.internal.CryptoUtils.sha256hash160(redeem.program());
        System.out.println("P2SH-P2WPKH mainnet " + LegacyAddress.fromScriptHash(main, redeemHash));
        System.out.println("P2SH-P2WPKH testnet " + LegacyAddress.fromScriptHash(test, redeemHash));

        System.out.println("P2WPKH      mainnet " + key.toAddress(ScriptType.P2WPKH, main));
        System.out.println("P2WPKH      testnet " + key.toAddress(ScriptType.P2WPKH, test));
        try {
            System.out.println("P2TR        mainnet " + key.toAddress(ScriptType.P2TR, main));
        } catch (RuntimeException e) {
            System.out.println("P2TR        non supportato da ECKey.toAddress: " + e);
        }
    }
}

package it.unipi.p2pb;

import org.bitcoinj.base.BitcoinNetwork;
import org.bitcoinj.base.Network;
import org.bitcoinj.base.ScriptType;
import org.bitcoinj.crypto.ECKey;

/** Esercizio 1 della slide 8: indirizzo P2PKH che inizia con una stringa scelta. */
public class Vanity {

    static final String BASE58 = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";

    public static ECKey vanity(String prefix, Network network) {
        for (char c : prefix.toCharArray())
            if (BASE58.indexOf(c) < 0)
                throw new IllegalArgumentException("'" + c + "' non esiste in base58 (mancano 0, O, I, l)");
        String target = "1" + prefix;                          // P2PKH mainnet comincia sempre con 1
        long tries = 0;
        long t0 = System.nanoTime();
        while (true) {
            tries++;
            ECKey key = new ECKey();                           // chiave casuale
            String addr = key.toAddress(ScriptType.P2PKH, network).toString();
            if (addr.startsWith(target)) {
                long ms = (System.nanoTime() - t0) / 1_000_000;
                System.out.println("Trovato dopo " + tries + " tentativi (" + ms + " ms)");
                System.out.println("Indirizzo   " + addr);
                System.out.println("Chiave WIF  " + key.getPrivateKeyAsWiF(network));  // senza questa l'indirizzo è inutile
                return key;
            }
        }
    }

    public static void main(String[] args) {
        String prefix = args.length > 0 ? args[0] : "Pi";
        vanity(prefix, BitcoinNetwork.MAINNET);
    }
}

