import org.bitcoinj.store.MemoryBlockStore;

/** Versione corretta di connectionTest: riprova davvero con un altro peer e non resta appesa per sempre. */
public class ConnectionFix {

    static final Sha256Hash BLOCK = Sha256Hash.wrap("0000000000000adc6423b570d751efcdf5e019d3d955fee155c28925913cb667");

    public static void main(String[] args) throws Exception {
        Context.propagate(new Context());   // evita l'errore "thread fixup" di bitcoinj
        NetworkParameters netParams = TestNet3Params.get();
        BlockChain chain = new BlockChain(netParams.network(), new MemoryBlockStore(netParams.getGenesisBlock()));
        PeerGroup peerGroup = new PeerGroup(netParams, chain);
        peerGroup.setUserAgent("Sample App", "1.0");
        peerGroup.addPeerDiscovery(new DnsDiscovery(netParams));
        peerGroup.start();

        long deadline = System.currentTimeMillis() + 120_000;          // al massimo 2 minuti
        Block block = null;
        int attempt = 0;
        while (block == null && System.currentTimeMillis() < deadline) {
            List<Peer> peers = peerGroup.getConnectedPeers();
            if (peers.isEmpty()) {
                System.out.println("nessun peer connesso, aspetto...");
                Thread.sleep(5000);
                continue;
            }
            Peer p = peers.get(attempt++ % peers.size());                // un peer diverso a ogni giro
            try {                                                       // il try sta DENTRO il ciclo
                block = p.getBlock(BLOCK).get(5, TimeUnit.SECONDS);
            } catch (TimeoutException | ExecutionException ex) {
                System.out.println("peer " + p.getAddr() + " non risponde, provo il prossimo");
            }
        }
        if (block != null) {
            System.out.println("Here is the block: " + block);
        } else {
            System.out.println("Nessun blocco entro il tempo limite: la rete P2P non è raggiungibile?");
        }
        ConnectionTest.printNetStats(peerGroup);
        peerGroup.stop();
    }
}

