/** Alternativa offline a getBlock(): legge un blocco serializzato (byte grezzi del messaggio "block") da file. */
public class ReadBlockFile {
    public static void main(String[] args) throws Exception {
        Context.propagate(new Context());          // verifyHeader lo richiede
        byte[] raw = Files.readAllBytes(Path.of(args.length > 0 ? args[0] : "block.bin"));
        Block block = Block.read(ByteBuffer.wrap(raw));
        Block.verifyHeader(block);                 // PoW: hash dell'header <= target codificato in nBits
        System.out.println("Letti " + raw.length + " byte, header valido (PoW ok)");
        System.out.println("Here is the block: " + block);
        GetBtcGenesis.printBlockInfo(block);
        System.out.println("Target   " + block.getDifficultyTargetAsInteger().toString(16));
    }
}

package it.unipi.p2pb;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import org.bitcoinj.base.Sha256Hash;

/** Rifà a mano quello che bitcoinj fa dentro Block: decodifica gli 80 byte dell'header e ne calcola l'hash. */
public class HeaderHash {

    /** I campi hash si mostrano con i byte invertiti rispetto a come sono serializzati. */
    static String reversedHex(byte[] b) {
        byte[] r = b.clone();
        for (int i = 0; i < r.length / 2; i++) { byte t = r[i]; r[i] = r[r.length - 1 - i]; r[r.length - 1 - i] = t; }
        return Util.bytesToHex(r);
    }

    public static void main(String[] args) throws Exception {
        byte[] raw = Files.readAllBytes(Path.of(args.length > 0 ? args[0] : "block.bin"));
        byte[] header = Arrays.copyOfRange(raw, 0, 80);
        ByteBuffer bb = ByteBuffer.wrap(header).order(ByteOrder.LITTLE_ENDIAN);   // interi little endian

        long version = Integer.toUnsignedLong(bb.getInt());
        byte[] prev = new byte[32];   bb.get(prev);
        byte[] merkle = new byte[32]; bb.get(merkle);
        long time = Integer.toUnsignedLong(bb.getInt());
        long bits = Integer.toUnsignedLong(bb.getInt());
        long nonce = Integer.toUnsignedLong(bb.getInt());

        System.out.println("version " + version + " (0x" + Long.toHexString(version) + ")");
        System.out.println("prev    " + reversedHex(prev));
        System.out.println("merkle  " + reversedHex(merkle));
        System.out.println("time    " + time);
        System.out.println("bits    0x" + Long.toHexString(bits));
        System.out.println("nonce   " + nonce);

        byte[] h = Sha256Hash.hashTwice(header);                 // SHA-256(SHA-256(header))
        System.out.println("hash    " + reversedHex(h));
    }
}
